import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the committed corpus generated by
/// `viamin/color_matching` PR #111 (see `docs/parity-corpus.md`).
///
/// Every case must select exactly the candidate the Elixir
/// `WeightedSquaredError` + `IlluminantMatching.best_match/4` reference
/// selects: lowest weighted squared error wins, the earliest candidate wins
/// on ties, and a candidate missing a measurement for any condition with
/// weight > 0 is excluded rather than scored against an implied zero.
///
/// Deliberately over the ~100-line class guideline: the corpus DTOs, loader,
/// builders, and assertions all serve this one parity contract, and splitting
/// them across files would spread the corpus schema across collaborators.
final class SolverParityCorpusTests: XCTestCase {
    private static let expectedSchema = "color-matching.parity-corpus.v1"
    private static let scoreAccuracy = 1e-12

    /// The committed corpus lives beside the test sources so the parity test
    /// reads it straight from the source tree (no SwiftPM resource
    /// declaration needed). See `docs/parity-corpus.md` for the refresh
    /// procedure.
    private static var corpusURL: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/ParityCorpus/parity_corpus.json")
    }

    // MARK: - Corpus DTOs (wire format of the parity corpus)

    private struct ParityCorpus: Codable {
        let schema: String
        let description: String?
        let source: Source?
        let cases: [Case]

        struct Source: Codable {
            let repository: String?
            let pullRequest: Int?
            let note: String?
        }

        struct Case: Codable {
            let id: String
            let description: String?
            let tags: [String]?
            let weights: Weights
            let target: [String: Double]
            let candidates: [Candidate]
            let expected: Expectation
        }

        struct Weights: Codable {
            let white: Double?
            let red: Double?
            let green: Double?
            let blue: Double?
            let lps: Double?
        }

        struct Candidate: Codable {
            let id: Int
            let name: String?
            let hex: String
            let responses: [String: Double]
        }

        struct Expectation: Codable {
            /// The candidate the reference implementation selects, or `nil`
            /// (JSON `null`) when every candidate must be excluded.
            let selectedCandidateId: Int?
            let score: Double?
            let excludedCandidateIds: [Int]?
        }
    }

    private enum CorpusFixtureError: Error, CustomStringConvertible {
        case fixtureMissing(URL)
        case invalidHex(String, caseID: String)
        case unknownLightSource(String, caseID: String)
        case activeConditionMissingFromTarget(LightingCondition, caseID: String)

        var description: String {
            switch self {
            case .fixtureMissing(let url):
                return "Parity corpus fixture not found at \(url.path). See docs/parity-corpus.md for the refresh procedure."
            case .invalidHex(let hex, let caseID):
                return "Case \(caseID): candidate hex \"\(hex)\" is not a valid #RRGGBB string."
            case .unknownLightSource(let key, let caseID):
                let canonical = LightingCondition.allCases.map { $0.rawValue }.joined(separator: ", ")
                return "Case \(caseID): light source \"\(key)\" is not a canonical condition (\(canonical))."
            case .activeConditionMissingFromTarget(let condition, let caseID):
                return "Case \(caseID): \(condition.rawValue) has positive weight but the target has no value for it."
            }
        }
    }

    // MARK: - Loading and building

    private func loadCorpus() throws -> ParityCorpus {
        let url = Self.corpusURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw CorpusFixtureError.fixtureMissing(url)
        }
        let data = try Data(contentsOf: url)
        do {
            let decoder = JSONDecoder()
            decoder.keyDecodingStrategy = .convertFromSnakeCase
            return try decoder.decode(ParityCorpus.self, from: data)
        } catch {
            XCTFail("Parity corpus at \(url.path) failed to decode: \(error)")
            throw error
        }
    }

    private func makeWeights(from dto: ParityCorpus.Weights) -> ChannelWeights {
        ChannelWeights(
            white: dto.white ?? 0,
            red: dto.red ?? 0,
            green: dto.green ?? 0,
            blue: dto.blue ?? 0,
            lps: dto.lps ?? 0
        )
    }

    private func makePalette(
        from candidates: [ParityCorpus.Candidate],
        caseID: String
    ) throws -> [PaletteColor] {
        try candidates.map { dto in
            guard let rgb = RGBColor(hex: dto.hex) else {
                throw CorpusFixtureError.invalidHex(dto.hex, caseID: caseID)
            }
            var responses: [LightingCondition: IlluminationResponse] = [:]
            for (key, value) in dto.responses {
                guard let condition = LightingCondition(rawValue: key) else {
                    throw CorpusFixtureError.unknownLightSource(key, caseID: caseID)
                }
                responses[condition] = IlluminationResponse(brightness: value)
            }
            return PaletteColor(id: dto.id, name: dto.name, hex: dto.hex, rgb: rgb, responses: responses)
        }
    }

    private func makeTarget(from dto: [String: Double], caseID: String) throws -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in dto {
            guard let condition = LightingCondition(rawValue: key) else {
                throw CorpusFixtureError.unknownLightSource(key, caseID: caseID)
            }
            brightness[condition] = value
        }
        return TargetResponseVector(brightness)
    }

    /// Mirrors `IlluminantMatching.best_match/4`: a strictly-lower score
    /// replaces the incumbent, so on a tie the earliest candidate in corpus
    /// order wins.
    private func bestMatch(
        in palette: [PaletteColor],
        target: TargetResponseVector,
        weights: ChannelWeights
    ) -> (index: Int, score: Double)? {
        let scorer = WeightedSquaredErrorScorer()
        var bestIndex: Int?
        var bestScore = Double.infinity
        for (index, candidate) in palette.enumerated() {
            guard case .score(let value) = scorer.score(candidate: candidate, target: target, weights: weights) else {
                continue
            }
            if value < bestScore {
                bestScore = value
                bestIndex = index
            }
        }
        guard let bestIndex else { return nil }
        return (bestIndex, bestScore)
    }

    // MARK: - Tests

    /// The corpus must be present, decodable, and self-consistent, and must
    /// keep covering the case classes that historically drift: ties and
    /// exclusions.
    func testCorpusFileLoadsAndHasValidShape() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.schema, Self.expectedSchema, "Unexpected corpus schema; update the loader in lockstep with docs/parity-corpus.md.")
        XCTAssertGreaterThanOrEqual(corpus.cases.count, 6, "The corpus must keep at least the seed-level coverage.")

        var problems: [String] = []
        var caseIDs = Set<String>()
        var tieCases = 0
        var exclusionCases = 0
        let knownKeys = Set(LightingCondition.allCases.map(\.rawValue))

        for testCase in corpus.cases {
            if !caseIDs.insert(testCase.id).inserted {
                problems.append("duplicate case id \"\(testCase.id)\"")
            }
            let tags = testCase.tags ?? []
            if tags.contains("tie") { tieCases += 1 }
            if tags.contains("exclusion") { exclusionCases += 1 }

            let candidateIDs = testCase.candidates.map(\.id)
            guard Set(candidateIDs).count == candidateIDs.count else {
                problems.append("case \(testCase.id): candidate ids must be unique")
                continue
            }
            for id in testCase.expected.excludedCandidateIds ?? [] where !candidateIDs.contains(id) {
                problems.append("case \(testCase.id): excluded id \(id) is not a candidate")
            }
            if let selectedID = testCase.expected.selectedCandidateId, !candidateIDs.contains(selectedID) {
                problems.append("case \(testCase.id): selected id \(selectedID) is not a candidate")
            }
            if testCase.expected.selectedCandidateId == nil,
               Set(testCase.expected.excludedCandidateIds ?? []) != Set(candidateIDs) {
                problems.append("case \(testCase.id): null selection must exclude exactly every candidate")
            }

            for key in testCase.target.keys where !knownKeys.contains(key) {
                problems.append("case \(testCase.id): target has unknown light source \"\(key)\"")
            }
            for candidate in testCase.candidates {
                for key in candidate.responses.keys where !knownKeys.contains(key) {
                    problems.append("case \(testCase.id): candidate \(candidate.id) has unknown light source \"\(key)\"")
                }
            }

            let weights = makeWeights(from: testCase.weights)
            for (condition, _) in weights.activeEntries where testCase.target[condition.rawValue] == nil {
                problems.append("case \(testCase.id): \(condition.rawValue) has positive weight but no target value")
            }
        }

        XCTAssertTrue(problems.isEmpty, "Corpus shape problems:\n" + problems.joined(separator: "\n"))
        XCTAssertGreaterThan(tieCases, 0, "The corpus must keep at least one tie case.")
        XCTAssertGreaterThan(exclusionCases, 0, "The corpus must keep at least one exclusion case.")
    }

    /// Scorer-level parity: `WeightedSquaredErrorScorer` selections must match
    /// the corpus exactly — including tie cases (earliest candidate wins) and
    /// exclusion cases (missing measurement on a required channel).
    func testScorerSelectionsMatchCorpusExactly() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for testCase in corpus.cases {
            let weights = makeWeights(from: testCase.weights)
            let palette = try makePalette(from: testCase.candidates, caseID: testCase.id)
            let target = try makeTarget(from: testCase.target, caseID: testCase.id)
            let expected = testCase.expected
            let expectedExcluded = Set(expected.excludedCandidateIds ?? [])

            for candidate in palette {
                let result = scorer.score(candidate: candidate, target: target, weights: weights)
                let isExcluded: Bool
                if case .excluded = result { isExcluded = true } else { isExcluded = false }
                XCTAssertEqual(
                    isExcluded,
                    expectedExcluded.contains(candidate.id),
                    "Case \(testCase.id): candidate \(candidate.id) exclusion mismatch (scorer returned \(result))."
                )
            }

            if let expectedID = expected.selectedCandidateId {
                let match = bestMatch(in: palette, target: target, weights: weights)
                XCTAssertEqual(
                    match.map { palette[$0.index].id },
                    expectedID,
                    "Case \(testCase.id): expected candidate \(expectedID) to be selected."
                )
                if let expectedScore = expected.score, let match {
                    XCTAssertEqual(
                        match.score,
                        expectedScore,
                        accuracy: Self.scoreAccuracy,
                        "Case \(testCase.id): winning score drifted from the corpus value."
                    )
                }
            } else {
                XCTAssertNil(
                    bestMatch(in: palette, target: target, weights: weights),
                    "Case \(testCase.id): every candidate is excluded, so no selection is possible."
                )
            }
        }
    }

    /// End-to-end parity through the production `CompositionSolver` fast path
    /// (the code the app actually runs), not just the scorer in isolation.
    func testSolverFastPathSelectionsMatchCorpus() throws {
        let corpus = try loadCorpus()
        let solver = CompositionSolver()

        for testCase in corpus.cases {
            let weights = makeWeights(from: testCase.weights)
            let palette = try makePalette(from: testCase.candidates, caseID: testCase.id)
            let target = try makeTarget(from: testCase.target, caseID: testCase.id)

            var grids: [LightingCondition: BrightnessGrid] = [:]
            for (condition, _) in weights.activeEntries {
                guard let value = target.value(for: condition) else {
                    throw CorpusFixtureError.activeConditionMissingFromTarget(condition, caseID: testCase.id)
                }
                grids[condition] = BrightnessGrid(width: 1, height: 1, fill: value)
            }

            let result = try solver.solve(palette: palette, sourceGrids: grids, weights: weights)
            let selectedIndex = result.colorIndex(x: 0, y: 0)

            if let expectedID = testCase.expected.selectedCandidateId {
                let index = try XCTUnwrap(selectedIndex, "Case \(testCase.id): solver left the cell unmatched.")
                XCTAssertEqual(
                    palette[index].id,
                    expectedID,
                    "Case \(testCase.id): solver fast path selected the wrong candidate."
                )
                if let expectedScore = testCase.expected.score {
                    XCTAssertEqual(
                        result.error(x: 0, y: 0),
                        expectedScore,
                        accuracy: Self.scoreAccuracy,
                        "Case \(testCase.id): solver error drifted from the corpus value."
                    )
                }
            } else {
                XCTAssertNil(
                    selectedIndex,
                    "Case \(testCase.id): every candidate is excluded, so the solver must leave the cell unmatched."
                )
                XCTAssertEqual(
                    result.error(x: 0, y: 0),
                    Double.infinity,
                    "Case \(testCase.id): an unmatched cell must carry infinite error."
                )
            }

            XCTAssertEqual(
                result.excludedCandidateCount,
                testCase.expected.excludedCandidateIds?.count ?? 0,
                "Case \(testCase.id): excluded-candidate count mismatch."
            )
        }
    }
}
